{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Ensure default network access rule for Storage Accounts is set to deny",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The `default_action` is set to \"Allow\", which permits public internet access to the storage account unless explicitly restricted by IP rules. This increases the attack surface and violates the principle of least privilege; it should be set to \"Deny\" to restrict access to only specified IPs or virtual networks."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\"]\n}",
  "fix_summary": "Changed the `default_action` from \"Allow\" to \"Deny\" in the `azurerm_storage_account_network_rules` resource to ensure that network access to the storage account is restricted by default, allowing only traffic from the specified IP rules."
}
